(()=>{const ids=['field','t2','broadening'],el=n=>document.getElementById('S06-'+n),zh=document.documentElement.lang.startsWith('zh'),controller=new AbortController();let value={};function update(){const field=+el('field').value,t2=+el('t2').value,broadening=+el('broadening').value,separation_Hz=.02*field,linewidth_Hz=1/(Math.PI*t2)+broadening,gamma=linewidth_Hz/2,L=(x,c)=>gamma/(Math.PI*((x-c)**2+gamma**2));const xx=Array.from({length:801},(_,i)=>-40+i*.1),yy=xx.map(x=>L(x,-separation_Hz/2)+L(x,separation_Hz/2)),peak=Math.max(...yy);value={field,t2,broadening,separation_Hz,linewidth_Hz,midpoint_to_peak:(L(0,-separation_Hz/2)+L(0,separation_Hz/2))/peak};ids.forEach(n=>el(n+'-value').textContent=value[n].toFixed(n==='field'?0:2));el('readout').textContent=(zh?'间隔 ':'Separation ')+separation_Hz.toFixed(2)+' Hz · '+(zh?'单峰半高全宽 ':'Individual FWHM ')+linewidth_Hz.toFixed(3)+' Hz · '+(zh?'中点 / 最高强度 ':'Midpoint / maximum ')+value.midpoint_to_peak.toFixed(3);const x=v=>70+(v+40)/80*760,y=v=>270-v/(peak*1.12)*210,path=fn=>xx.map((v,i)=>(i?'L':'M')+x(v).toFixed(2)+','+y(fn(v)).toFixed(2)).join(' ');let svg='<svg viewBox="0 0 900 340" role="img" aria-label="'+(zh?'两条邻近洛伦兹线及总和':'Two neighboring Lorentzian lines and their sum')+'" style="width:100%;height:auto;background:#fbfaf6"><path d="M70,55V270H830" fill="none" stroke="#84969b"/>';for(let v=-40;v<=40;v+=10)svg+='<text x="'+x(v)+'" y="293" text-anchor="middle" font-size="13">'+v+'</text>';for(let i=0;i<=3;i++){const v=peak*i/3;svg+='<text x="62" y="'+(y(v)+4)+'" text-anchor="end" font-size="12">'+v.toFixed(3)+'</text>';}for(const c of [-separation_Hz/2,separation_Hz/2])svg+='<path d="'+path(v=>L(v,c))+'" fill="none" stroke="#82b9b3" stroke-width="2"/>';svg+='<path d="'+path(v=>L(v,-separation_Hz/2)+L(v,separation_Hz/2))+'" fill="none" stroke="#265f85" stroke-width="3"/><text x="70" y="28" font-size="15">'+(zh?'频谱密度 / 相对面积 Hz⁻¹':'Spectral density / relative area Hz⁻¹')+'</text><text x="450" y="325" text-anchor="middle" font-size="14">'+(zh?'相对于两线中点的频率 / Hz':'Frequency relative to the pair midpoint / Hz')+'</text></svg>';el('plot').innerHTML=svg;}
function set(p){ids.forEach(n=>{if(n in p)el(n).value=p[n]});update();return{...value}}function reset(){return set({field:400,t2:.2,broadening:0})}ids.forEach(n=>el(n).addEventListener('input',update,{signal:controller.signal}));el('reset').addEventListener('click',reset,{signal:controller.signal});window.CourseLab={set,state:()=>({...value}),reset,destroy:()=>controller.abort()};update();})();
